<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { Bookmark, ChevronDown, Pencil, Plus, RefreshCw, Trash2, X } from 'lucide-vue-next'
import type { LibraryGame } from '../shared/types'
import { filterLibraryGames, type LibraryFilters, type LibrarySort } from '../library-workspace'
import { describeSavedView, sameSavedFilters, type SavedLibraryView, type SavedViewEditor } from '../saved-library-views'

const props = defineProps<{ views: SavedLibraryView[]; games: LibraryGame[]; filters: LibraryFilters; sort: LibrarySort; activeId: string | null; editor: SavedViewEditor | null; error: string | null; disabled: boolean; readOnly: boolean; canSave: boolean }>()
const emit = defineEmits<{ apply: [view: SavedLibraryView]; create: [event: MouseEvent]; rename: [id: string, event: MouseEvent]; save: [name: string]; update: [id: string]; remove: [id: string]; close: []; retry: [] }>()
const manage = ref(false), name = ref(''), nameInput = ref<HTMLInputElement | null>(null)
watch(() => props.editor, async editor => { name.value = editor?.name ?? ''; if (editor) { await nextTick(); nameInput.value?.focus() } }, { immediate: true })
const counts = computed(() => new Map(props.views.map(view => [view.id, filterLibraryGames(props.games, view.filters, view.sort).length])))
const quickViews = computed(() => {
  const first = props.views.slice(0, 6), current = props.views.find(view => view.id === props.activeId)
  return current && !first.includes(current) ? [...first.slice(0, 5), current] : first
})
const active = computed(() => props.views.find(view => view.id === props.activeId))
const adjusted = computed(() => !!active.value && (!sameSavedFilters(active.value.filters, props.filters) || active.value.sort !== props.sort))
const categories = computed(() => new Set(props.games.flatMap(game => game.categories)))
const tags = computed(() => new Set(props.games.flatMap(game => [...game.customTags, ...(game.metadata?.tags ?? [])])))
function missing(view: SavedLibraryView): string {
  return [view.filters.category && !categories.value.has(view.filters.category) ? '原分类已不存在' : '', view.filters.tag && !tags.value.has(view.filters.tag) ? '原标签已不存在' : ''].filter(Boolean).join('，')
}
</script>

<template>
  <section v-if="views.length || editor || error" class="saved-views" aria-label="常用筛选">
    <div class="saved-views-heading"><strong><Bookmark :size="16" /> 常用筛选 <small>{{ views.length }}</small></strong><div class="saved-views-actions"><button v-if="canSave && views.length" :disabled="disabled || readOnly" @click="emit('create', $event)"><Plus :size="14" /> 保存当前筛选</button><button v-if="views.length" :aria-expanded="manage" :disabled="disabled" @click="manage = !manage"><ChevronDown :size="14" /> {{ manage ? '收起管理' : '管理常用筛选' }}</button></div></div>
    <div v-if="views.length" class="saved-views-quick"><button v-for="view in quickViews" :key="view.id" :title="describeSavedView(view)" :aria-label="`打开常用筛选：${view.name}，${counts.get(view.id)}部作品`" :aria-pressed="activeId === view.id && !adjusted" :disabled="disabled" @click="emit('apply', view)"><span>{{ view.name }}</span><small>{{ counts.get(view.id) }}</small></button><button v-if="views.length > 6 && !manage" class="saved-more" @click="manage = true">全部 {{ views.length }} 个 <ChevronDown :size="14" /></button></div>
    <p v-if="active" class="saved-active" role="status">当前：<strong>{{ active.name }}</strong><span v-if="adjusted"> · 已调整，保存的条件未改变</span><span v-else> · 随书架实时更新</span><span v-if="missing(active)" class="saved-missing"> · {{ missing(active) }}，原条件仍保留</span></p>
    <form v-if="editor" class="saved-view-editor" aria-label="保存常用筛选" @submit.prevent="emit('save', name)" @keydown.esc.stop.prevent="emit('close')"><label>{{ editor.id ? '新名称' : '给这组筛选起个名字' }}<input ref="nameInput" v-model="name" maxlength="80" aria-label="常用筛选名称" placeholder="例如：周末想读的短篇" :disabled="disabled || readOnly" /></label><div class="saved-editor-actions"><button type="submit" :disabled="disabled || readOnly">{{ editor.id ? '保存名称' : '保存筛选' }}</button><button type="button" :disabled="disabled" @click="emit('close')"><X :size="14" /> 取消</button></div><p>{{ editor.id ? '只修改名称，原来的筛选条件不变。' : describeSavedView({ filters, sort }) }}</p></form>
    <div v-if="error" class="saved-views-error" role="alert"><span>{{ error }}</span><button v-if="readOnly" :disabled="disabled" @click="emit('retry')">重新读取</button></div>
    <div v-if="manage" class="saved-views-manager"><p>保存的是筛选条件，作品增减后结果会自动更新。仅保存在本机，不随书架备份导出。</p><ul><li v-for="view in views" :key="view.id"><div><strong>{{ view.name }}</strong><span>{{ counts.get(view.id) }} 部作品 · {{ describeSavedView(view) }}</span><small v-if="missing(view)" class="saved-missing">{{ missing(view) }}；打开后可移除该条件。</small></div><div class="saved-manager-actions"><button :disabled="disabled" :aria-label="`打开筛选：${view.name}`" @click="emit('apply', view)">打开</button><button :disabled="disabled || readOnly" :aria-label="`重命名筛选：${view.name}`" @click="emit('rename', view.id, $event)"><Pencil :size="14" /> 改名</button><button v-if="canSave" :disabled="disabled || readOnly" :aria-label="`更新筛选条件：${view.name}`" @click="emit('update', view.id)"><RefreshCw :size="14" /> 更新为当前筛选</button><button :disabled="disabled || readOnly" :aria-label="`删除筛选：${view.name}`" @click="emit('remove', view.id)"><Trash2 :size="14" /> 删除</button></div></li></ul></div>
  </section>
</template>

<style scoped>
.saved-views{min-width:0;margin:16px 0 22px;padding:14px 16px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink)}.saved-views-heading,.saved-views-heading>strong,.saved-views-actions,.saved-views-quick,.saved-editor-actions,.saved-manager-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.saved-views-heading{justify-content:space-between}.saved-views-heading>strong{font-size:14px;gap:7px}.saved-views-heading small{font-size:12px;font-weight:400;color:var(--muted)}.saved-views-actions button,.saved-editor-actions button,.saved-manager-actions button,.saved-more{display:inline-flex;align-items:center;gap:5px;font-size:12px;color:var(--blue);padding:5px 3px}.saved-views-quick{margin-top:12px;gap:8px}.saved-views-quick>button:not(.saved-more){display:flex;align-items:center;gap:10px;max-width:min(100%,240px);padding:7px 11px;border:1px solid var(--line);border-radius:8px;font-size:13px;text-align:left}.saved-views-quick>button[aria-pressed=true]{background:var(--blue-soft);border-color:var(--blue);color:var(--blue)}.saved-views-quick button>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.saved-views-quick small{font-size:12px;color:var(--muted);flex:none}.saved-active{margin:10px 0 0;font-size:12px;line-height:1.7;color:var(--muted);overflow-wrap:anywhere}.saved-active strong{font-weight:500;color:var(--ink)}.saved-missing{color:var(--muted)}.saved-view-editor{margin-top:14px;border-top:1px solid var(--line);padding-top:14px;display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;min-width:0}.saved-view-editor label{display:flex;flex-direction:column;gap:6px;flex:1;min-width:min(100%,200px);font-size:13px}.saved-view-editor input{min-width:0;width:100%;border:1px solid var(--line);padding:9px 11px;background:var(--surface);border-radius:7px;font-size:14px;color:var(--ink)}.saved-view-editor p{flex-basis:100%;font-size:12px;line-height:1.7;color:var(--muted);overflow-wrap:anywhere}.saved-editor-actions>button:first-child{border:1px solid var(--blue);border-radius:7px;padding:9px 13px}.saved-views-error{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:12px;font-size:13px;line-height:1.7;color:var(--ink);overflow-wrap:anywhere}.saved-views-error button{color:var(--blue)}.saved-views-manager{margin-top:15px;padding-top:12px;border-top:1px solid var(--line)}.saved-views-manager>p{font-size:12px;color:var(--muted);line-height:1.7;margin-bottom:10px}.saved-views-manager ul{list-style:none;margin:0;padding:0}.saved-views-manager li{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;border-top:1px solid var(--line);padding:12px 0}.saved-views-manager li>div:first-child{min-width:0;flex:1;flex-basis:260px;display:flex;flex-direction:column;gap:5px;overflow-wrap:anywhere}.saved-views-manager strong{font-size:14px;font-weight:600}.saved-views-manager span,.saved-views-manager small{font-size:12px;line-height:1.7;color:var(--muted)}.saved-manager-actions{gap:12px}.saved-views button:disabled{opacity:.5;cursor:not-allowed}.saved-views button:focus-visible,.saved-view-editor input:focus-visible{outline:2px solid var(--blue);outline-offset:3px}@media(max-width:700px){.saved-views{padding:12px}.saved-views-heading{align-items:flex-start}.saved-views-actions{gap:8px}.saved-views-manager li>div:first-child{flex-basis:100%}.saved-editor-actions{margin-left:auto}}
</style>
